from typing import List, Tuple, Optional, Set
import time


Grid = List[List[int]]
Point = Tuple[int, int]


def validate_maze_boundary(maze: Grid, start: Point, end: Point) -> bool:
    """Check that the maze boundary is walls except for the entrance and exit."""
    if not maze or not maze[0]:
        return False

    rows = len(maze)
    cols = len(maze[0])
    sr, sc = start
    er, ec = end

    def is_boundary(r: int, c: int) -> bool:
        return r == 0 or c == 0 or r == rows - 1 or c == cols - 1

    for r in range(rows):
        if len(maze[r]) != cols:
            return False
        for c in range(cols):
            if is_boundary(r, c) and (r, c) not in {start, end} and maze[r][c] != 1:
                return False

    return True


def shortest_path_bfs(maze: Grid, start: Point, end: Point) -> Optional[List[Point]]:
    """
    Find the shortest path from start to end in a maze using BFS.
    """
    if not maze or not maze[0]:
        return None

    rows = len(maze)
    cols = len(maze[0])

    sr, sc = start
    er, ec = end

    def in_bounds(r: int, c: int) -> bool:
        return 0 <= r < rows and 0 <= c < cols

    if not in_bounds(sr, sc) or not in_bounds(er, ec):
        return None
    if maze[sr][sc] != 0 or maze[er][ec] != 0:
        return None

    directions = [(1, 0), (-1, 0), (0, 1), (0, -1)]
    queue = deque([start])
    visited = {start}
    parent = {start: None}

    while queue:
        r, c = queue.popleft()
        if (r, c) == end:
            break

        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if in_bounds(nr, nc) and maze[nr][nc] == 0 and (nr, nc) not in visited:
                visited.add((nr, nc))
                parent[(nr, nc)] = (r, c)
                queue.append((nr, nc))

    if end not in parent:
        return None

    path = []
    cur = end
    while cur is not None:
        path.append(cur)
        cur = parent[cur]
    path.reverse()
    return path


def visualize_bfs_search(
    maze: Grid,
    start: Point,
    end: Point,
    delay: float = 0.3,
) -> Optional[List[Point]]:
